from pysat.solvers import Cadical153, Glucose3, Minisat22
from pysat.card import CardEnc, EncType
from pysat.formula import IDPool
import time, itertools, sys
N=20; M=46
edges=[]
for g in range(5):
    for i in range(4):
        for j in range(i+1,4):
            edges.append((g*4+i,g*4+j,('intra',g,i,j)))
for g in range(4):
    for i in range(4):
        edges.append((g*4+i,(g+1)*4+i,('vert',g,i)))
assert len(edges)==46
vpool=IDPool()
def X(v,l): return vpool.id(('x',v,l))
def Y(e,d): return vpool.id(('y',e,d))
clauses=[]
# vertex exactly one label
for v in range(N):
    lits=[X(v,l) for l in range(M+1)]
    clauses.append(lits)
    # pairwise atmost
    for a in range(M+1):
        xa=X(v,a)
        for b in range(a+1,M+1):
            clauses.append([-xa,-X(v,b)])
# labels at most one vertex
for l in range(M+1):
    for u in range(N):
        xu=X(u,l)
        for v in range(u+1,N):
            clauses.append([-xu,-X(v,l)])
# edge exactly one diff
for e in range(len(edges)):
    lits=[Y(e,d) for d in range(1,M+1)]
    clauses.append(lits)
    for d1 in range(1,M+1):
        yd=Y(e,d1)
        for d2 in range(d1+1,M+1):
            clauses.append([-yd,-Y(e,d2)])
# each diff exactly one edge (at least+atmost)
for d in range(1,M+1):
    lits=[Y(e,d) for e in range(len(edges))]
    clauses.append(lits)
    for e1 in range(len(edges)):
        y1=Y(e1,d)
        for e2 in range(e1+1,len(edges)):
            clauses.append([-y1,-Y(e2,d)])
# link endpoint labels -> y
for e,(u,v,info) in enumerate(edges):
    for a in range(M+1):
        xu=X(u,a)
        for b in range(M+1):
            if a==b: continue
            clauses.append([-xu, -X(v,b), Y(e, abs(a-b))])
print('vars', vpool.top, 'clauses', len(clauses))
# optional require 0,46 on vertices? follows from y46 link and edge? labels assigned => yes endpoints diff46. But add at least one label 0/46 maybe not needed.
# Solve
for SolverCls in [Cadical153, Glucose3, Minisat22]:
    print('try', SolverCls)
    t=time.time()
    with SolverCls(bootstrap_with=clauses) as s:
        res=s.solve()
        print('res',res,'time',time.time()-t)
        if res:
            model=set(s.get_model())
            sol=[]
            for v in range(N):
                labs=[l for l in range(M+1) if X(v,l) in model]
                sol.append(labs[0] if labs else None)
            print(sol)
            diffs=[abs(sol[u]-sol[v]) for u,v,_ in edges]
            print(len(set(diffs)), sorted(diffs)[:], 'labels unique', len(set(sol)))
            sys.exit()

from pysat.solvers import Cadical153, Glucose3
import time, sys
N=20; M=46
edges=[]
for g in range(5):
    for i in range(4):
        for j in range(i+1,4):
            edges.append((g*4+i,g*4+j,('intra',g,i,j)))
for g in range(4):
    for i in range(4):
        edges.append((g*4+i,(g+1)*4+i,('vert',g,i)))
# variable ids via formulas
num_x=N*(M+1)
def X(v,l): return v*(M+1)+l+1
def Y(e,d): return num_x + e*M + d  # d 1..M; yields ... +1..+46
clauses=[]
# exactly one label per vertex pairwise
for v in range(N):
    clauses.append([X(v,l) for l in range(M+1)])
    for a in range(M+1):
        xa=X(v,a)
        for b in range(a+1,M+1): clauses.append([-xa,-X(v,b)])
# label at most one vertex
for l in range(M+1):
    for u in range(N):
        xu=X(u,l)
        for v in range(u+1,N): clauses.append([-xu,-X(v,l)])
# edge exactly one diff (at least one maybe with atmost)
for e in range(len(edges)):
    clauses.append([Y(e,d) for d in range(1,M+1)])
    for d1 in range(1,M+1):
        y=Y(e,d1)
        for d2 in range(d1+1,M+1): clauses.append([-y,-Y(e,d2)])
# diff at most one edge
for d in range(1,M+1):
    for e1 in range(len(edges)):
        y=Y(e1,d)
        for e2 in range(e1+1,len(edges)): clauses.append([-y,-Y(e2,d)])
# link actual label pair => diff
for e,(u,v,info) in enumerate(edges):
    for a in range(M+1):
        xa=X(u,a)
        for b in range(M+1):
            if a!=b:
                clauses.append([-xa,-X(v,b),Y(e,abs(a-b))])
print('built vars', num_x+len(edges)*M, 'clauses',len(clauses), flush=True)
# edge orbit representatives for diff46: actual edges grouped
reps=[]
# all possible branch first maybe all 46? try with fixed labels for each edge
# We'll branch through every edge, complement orientation as X(u,0),X(v,46), but graph automorphism not necessary; reversed orientation by complement so okay for unordered edge.
order=list(range(len(edges)))
# sort put representative? high-degree all same degree? all vertices degree 4-5-?
# Try all edges with 10 sec each via solver.conf_budget? no simple time. Use one solve per process? Cadical has no timeout.
start=time.time()
for idx,eidx in enumerate(order):
    u,v,info=edges[eidx]
    print('branch',idx,eidx,info,u,v,'elapsed',time.time()-start,flush=True)
    with Cadical153(bootstrap_with=clauses) as s:
        res=s.solve(assumptions=[X(u,0),X(v,46),Y(eidx,46)])
        print(' res',res,'elapsed',time.time()-start,flush=True)
        if res:
            model=set(s.get_model())
            sol=[]
            for vv in range(N):
                labs=[l for l in range(M+1) if X(vv,l) in model]
                sol.append(labs[0])
            print('SOL',sol,flush=True)
            diffs=[abs(sol[a]-sol[b]) for a,b,_ in edges]
            print('check', len(set(sol)), len(set(diffs)), sorted(diffs), flush=True)
            sys.exit()
    if time.time()-start>55: break
